plugins {
	java
}

group = "tw.moses"
version = "1.0.0"

repositories {
	mavenCentral()
	maven {
		name = "papermc"
		url = uri("https://repo.papermc.io/repository/maven-public/")
	}
}

dependencies {
	compileOnly("io.papermc.paper:paper-api:26.3.build.230-stable")
}

java {
	toolchain.languageVersion.set(JavaLanguageVersion.of(25))
}

